  put(root,source);put(folder+"/project/parts/formula.tex","\\begin{frame}{Precision}\n\\begin{equation}\\label{eq:precision}\n\\operatorname{SE}(\\bar X_n)=\\frac{\\sigma}{\\sqrt n}\n\\end{equation}\n\\begin{equation}\\label{eq:offset}\nE[X]=0\n\\end{equation}\n\\pause\nFour times the sample size halves the standard error.\n\\end{frame}\n");
