  if(auto *card=w->findChild<QFrame *>("researchReferenceCard")){check("source hover card fits source viewport",QRect(w->editor()->viewport()->mapToGlobal(QPoint()),w->editor()->viewport()->size()).contains(card->geometry()));card->grab().save(folder+"/source-card.png");}
