  const auto articleRoot=folder+"/article/main.tex";const QString article="\\documentclass{article}\n\\usepackage{amsmath,hyperref}\n\\begin{document}\n\\begin{equation}\\label{eq:ordinary}x+y=z\\end{equation}\nSee \\eqref{eq:ordinary}.\n\\end{document}\n";put(articleRoot,article);auto *paper=new TeXDocumentWindow(articleRoot);paper->show();for(int pass=0;pass<2;++pass){paper->typeset();waitFor([&]{return !paper->isTypesetting()&&!paper->property("researchBuildPreparing").toBool()&&!paper->property("researchBuildFinishing").toBool()&&!paper->property("researchPublishing").toBool();},100000);settle(300);}Research::Request ordinary;ordinary.root=articleRoot;ordinary.pdf=Research::previewFile(articleRoot);ordinary.key="eq:ordinary";ordinary.buffers=Research::buffers();const auto ordinaryFormula=Research::work(ordinary);check("ordinary article equation still resolves correctly",ordinaryFormula.visual()&&ordinaryFormula.target.number=="1"&&ordinaryFormula.page==0);paper->setModified(false);app.exit(failures?1:0);
